#!/usr/bin/env bash
# Print the three most frequent IPs in access.log, one per line,
# most frequent first; ties broken by first appearance in the log.
set -eu

awk '
{
    ip = $1
    if (!(ip in count)) {
        order[++n] = ip
    }
    count[ip]++
}
END {
    for (i = 1; i <= n; i++) {
        ip = order[i]
        # rank = count (primary), first-appearance index (secondary, ascending)
        printf "%012d %d %s\n", count[ip], i, ip
    }
}
' access.log | sort -k1,1nr -k2,2n | head -3 | awk '{print $3}'
